o.append(f'\tinline constexpr std::uint32_t kHallFang = 0x{IDS[("ACTI", "hall_fang")]:03X}, kHallRobes = 0x{IDS[("ACTI", "hall_robes")]:03X}, kHallSkull = 0x{IDS[("ACTI", "hall_skull")]:03X}, kHallEndless = 0x{IDS[("ACTI", "hall_endless")]:03X}, kHallThrone = 0x{IDS[("ACTI", "hall_throne")]:03X}, kHallFangShow = 0x{IDS[("STAT", "hall_fang_show")]:03X}, kFangWeap = 0x{IDS[("WEAP", "fang")]:03X};')
o.append('\tinline constexpr std::array<std::uint32_t, 5> kEmmFx{ ' + ', '.join(f'0x{IDS[("ACTI", "emm_" + k)]:03X}' for k in ('summon', 'crystal', 'orb', 'storm', 'tornado')) + ' };  // summon, crystal, orb, storm, tornado')
o.append('\tinline constexpr std::array<std::uint32_t, 6> kTornado{ ' + ', '.join(f'0x{IDS[("ACTI", "emm_tornado")]:03X}' if k == 'fire' else f'0x{IDS[("ACTI", "tornado_" + k)]:03X}' for k in ('fire', 'frost', 'shock', 'wind', 'sun', 'blood')) + ' };  // by element (Bows Kind order)')
rl, kl = EC['relic'], EC['kill']
o.append('\tinline constexpr std::array<int, 6> kEchoGuards{ ' + ', '.join(map(str, rl['guards'])) + ' }, kEchoElites{ ' + ', '.join(map(str, rl['elites'])) + ' }, kEchoKillN{ ' + ', '.join(map(str, kl['n'])) + ' };  // per Skyrim difficulty')
o.append(f'\tinline constexpr float kEchoWake = {F(rl["wakeRange"])}, kEchoTake = {F(rl["takeRange"])}, kEchoKillRadius = {F(kl["radius"])}, kEchoStoneTake = {F(EC["stone"]["takeRange"])};')
stone = next(r for r in S['dressing']['rows'] if r['id'] == 'echo_stone')
o.append(f'\tinline constexpr float kEchoStoneX = {F(stone["x"])}, kEchoStoneY = {F(stone["y"])};  // the Echo Stone on a freed altar (dressing: echo_stone)')
RL = EC['reliquary']
P4 = lambda v, yaw=0: f'{{ {F(v[0])}, {F(v[1])}, {F(v[2])}, {F(yaw)} }}'
o.append('\tstruct RelSpot { float x, y, z, yaw; };')
o.append(f'\tinline constexpr std::string_view kRelCell = {cs(RL["cell"])};')
o.append(f'\tinline constexpr RelSpot kRelDoor{P4(RL["door"], RL["doorYaw"])}, kRelRoomAt{P4(RL["room"])}, kRelArrive{P4(RL["arrive"], RL["arriveYaw"])}, kRelExit{P4(RL["exitDoor"], RL["exitYaw"])}, kRelLeave{P4(RL["leave"], RL["leaveYaw"])};  // door/leave: in the cell; arrive/exit: in the room\'s frame')
o.append(f'\tinline constexpr std::array<RelSpot, 4> kRelPedestals{{ {{ ' + ', '.join(P4(q[:3], q[3]) for q in RL['pedestals']) + ' } };')
o.append(f'\tinline constexpr float kRelUse = {F(RL["useRange"])};')
o.append(f'\tinline constexpr std::uint32_t kRelDoorIn = 0x{IDS[("ACTI", "rel_door_in")]:03X}, kRelDoorOut = 0x{IDS[("ACTI", "rel_door_out")]:03X}, kRelRoom = 0x{IDS[("STAT", "rel_room")]:03X}, kRelRelic = 0x{IDS[("STAT", "rel_relic")]:03X}, '
         f'kRelBlue = 0x{IDS[("LIGH", "rel_blue")]:03X}, kRelWarm = 0x{IDS[("LIGH", "rel_warm")]:03X}, kRelRelicLight = 0x{IDS[("LIGH", "rel_relic")]:03X}, kRelBeam = 0x{IDS[("STAT", "shrine_freed_beam")]:03X}, '
         f'kRelBrazier = 0x{IDS[("STAT", "rel_brazier")]:03X}, kRelStone = 0x{IDS[("STAT", "echo_stone")]:03X}, kRelBanner = 0x{IDS[("STAT", "rel_banner")]:03X};')
# (Noah) the hidden quests (sheet: eggs, src/Eggs.cpp)
EG = S['eggs']['rows']
_rowi = {r['id']: i for i, r in enumerate(en)}
STEPT = ['touch', 'order', 'altar', 'kills', 'survive', 'boss', 'classkills']
ELEM = ['any', 'fire', 'frost', 'shock']
CLS = ['summoner', 'destruction', 'ranger', 'spellsword']
o.append('\tstruct EggStep { int type, n, element; bool night; float r0, r1; bool nodamage; float seconds; std::string_view name, text; int row; bool dark; std::string_view hint; };')
o.append('\tenum EggStepType : int { ' + ', '.join(f'kEgg{t.capitalize()} = {i}' for i, t in enumerate(STEPT)) + ' };')
o.append('\tstruct EggDef { std::string_view id, title, rewardText; int cls; std::array<EggStep, 8> steps; int nSteps; std::uint32_t glob, townGlob; };  // (one per class: it wins the class wonder)')
o.append(f'\tinline constexpr std::uint32_t kEggGifts = 0x{IDS[("GLOB", "egg_gifts")]:03X}, kTestKitGlob = 0x{IDS[("GLOB", "test_kit")]:03X}, kRitualSouls = 0x{IDS[("GLOB", "ritual_souls")]:03X}, kRitualStand = 0x{IDS[("GLOB", "ritual_stand")]:03X};')
o.append(f'\tinline constexpr std::array<EggDef, {len(EG)}> kEggs{{ {{')
for e in EG:
    st = e['steps'] + [dict(type='altar', n=0, text='', element='any', night=False, r0=0, r1=0, nodamage=False, seconds=0, name='', row='none', dark=False, hint='')] * (8 - len(e['steps']))
    steps = ', '.join(f'EggStep{{ {STEPT.index(s["type"])}, {s["n"]}, {ELEM.index(s["element"])}, {str(s["night"]).lower()}, {F(s["r0"])}, {F(s["r1"])}, {str(s["nodamage"]).lower()}, {F(s["seconds"])}, {cs(s["name"])}, {cs(s["text"])}, {_rowi[s["row"]] if s["row"] != "none" else -1}, {str(s["dark"]).lower()}, {cs(s.get("hint", ""))} }}' for s in st)
    o.append(f'\t\tEggDef{{ {cs(e["id"])}, {cs(e["title"])}, {cs(e["rewardText"])}, {CLS.index(e["cls"])}, {{ {steps} }}, {len(e["steps"])}, 0x{IDS[("GLOB", "egg_" + e["id"])]:03X}, 0x{IDS[("GLOB", "egg_" + e["id"] + "_town")]:03X} }},')
o.append('\t} };')
o.append('}')
with open(root / 'src/Generated.h', 'a') as f: f.write('\n'.join(o) + '\n')
print('appended v0.2 tables')

# (Noah: Legendary spells in gold in the inventory too) Inventory Interface Information Injector can't colour a name, so a
# Legendary spell (coffer tier 3) gets a gold icon and "Legendary" as its school line in the Magic menu
_i4 = root / 'assets/fx/SKSE/Plugins/InventoryInjector/CurseOfAlduin.json'
_rules = [
    {"match": {"formType": "MiscItem", "formId": {"anyOf": ["Paragliding.esp|802"]}},
     "assign": {"subTypeDisplay": "Dragon", "iconSource": "skyui/icons_item_psychosteve.swf", "iconLabel": "misc_dragonclaw", "iconColor": "#e0b060"}},
]
_leg = [f'{r["plugin"]}|{int(r["formId"], 16):X}' for r in S['coffer_spells']['rows'] if int(r.get('tier', 0)) >= 3]
if _leg:
    _rules.append({"match": {"formType": "Spell", "formId": {"anyOf": _leg}},
                   "assign": {"iconColor": "#ffc94a", "infoSchoolName": "Legendary"}})
with open(_i4, 'w', newline='\n') as f:
    json.dump({"$schema": "https://raw.githubusercontent.com/Exit-9B/InventoryInjector/main/docs/InventoryInjector.schema.json", "rules": _rules}, f, indent=2)
    f.write('\n')
print('wrote', _i4.name, len(_leg), 'legendary spells')
